#if !defined(MEETUP_H)
#define MEETUP_H

#include <string>

namespace meetup {

enum class Month {
    January = 1,
    February,
    March,
    April,
    May,
    June,
    July,
    August,
    September,
    October,
    November,
    December
};

enum class Weekday {
    Sunday = 0,
    Monday,
    Tuesday,
    Wednesday,
    Thursday,
    Friday,
    Saturday
};

enum class Schedule {
    first,
    second,
    third,
    fourth,
    last,
    teenth,

    First = first,
    Second = second,
    Third = third,
    Fourth = fourth,
    Last = last,
    Teenth = teenth
};

class Meetup {
public:
    Meetup(int year, int month);
    Meetup(int year, Month month);

    std::string day(Weekday weekday, Schedule schedule) const;

private:
    int year_;
    int month_;
};

using meetup = Meetup;

}  // namespace meetup

#endif  // MEETUP_H
