#include "meetup.h"

#include <iomanip>
#include <sstream>
#include <string>

namespace meetup {
namespace {

bool is_leap_year(int year)
{
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

int days_in_month(int year, int month)
{
    switch (month) {
    case 2:
        return is_leap_year(year) ? 29 : 28;
    case 4:
    case 6:
    case 9:
    case 11:
        return 30;
    default:
        return 31;
    }
}

// Returns the weekday for a Gregorian calendar date, with Sunday as 0.
int weekday_for_date(int year, int month, int day)
{
    static const int month_offsets[] = {
        0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4
    };

    if (month < 3) {
        --year;
    }

    return (year + year / 4 - year / 100 + year / 400
            + month_offsets[month - 1] + day) % 7;
}

std::string format_date(int year, int month, int day)
{
    std::ostringstream result;
    result << std::setfill('0')
           << std::setw(4) << year << '-'
           << std::setw(2) << month << '-'
           << std::setw(2) << day;
    return result.str();
}

}  // namespace

Meetup::Meetup(int year, int month)
    : year_(year), month_(month)
{
}

Meetup::Meetup(int year, Month month)
    : Meetup(year, static_cast<int>(month))
{
}

std::string Meetup::day(Weekday weekday, Schedule schedule) const
{
    const int target_weekday = static_cast<int>(weekday);
    const int last_day = days_in_month(year_, month_);

    if (schedule == Schedule::teenth) {
        for (int date = 13; date <= 19; ++date) {
            if (weekday_for_date(year_, month_, date) == target_weekday) {
                return format_date(year_, month_, date);
            }
        }
    } else if (schedule == Schedule::last) {
        for (int date = last_day; date >= 1; --date) {
            if (weekday_for_date(year_, month_, date) == target_weekday) {
                return format_date(year_, month_, date);
            }
        }
    } else {
        const int occurrence = [&] {
            switch (schedule) {
            case Schedule::first:
                return 1;
            case Schedule::second:
                return 2;
            case Schedule::third:
                return 3;
            case Schedule::fourth:
                return 4;
            default:
                return 0;
            }
        }();

        int count = 0;
        for (int date = 1; date <= last_day; ++date) {
            if (weekday_for_date(year_, month_, date) == target_weekday) {
                ++count;
                if (count == occurrence) {
                    return format_date(year_, month_, date);
                }
            }
        }
    }

    return {};
}

}  // namespace meetup
